 tools.web_fetch({ url: "https://cdn.jsdelivr.net/gh/Ebony-Vinyl/dsh-our-free-model@main/feed/manifest.json" }),
 tools.pwsh({ command: "cd 'C:\\Users\\jjq21\\Desktop\\github\\dsh-our-free-model'; git ls-remote origin main 2>&1; echo '--- local HEAD ---'; git rev-parse HEAD; echo '--- stale origin/main ---'; git rev-parse origin/main", description: "Compare upstream main with local clone" }),
